import{_ as t,o as s,c as a,a2 as o}from"./chunks/framework.CMpzMyBe.js";const g=JSON.parse('{"title":"Scraping internal telemetry","description":"","frontmatter":{},"headers":[],"relativePath":"agent-data-plane/telemetry.md","filePath":"agent-data-plane/telemetry.md","lastUpdated":1794344758000}'),i={name:"agent-data-plane/telemetry.md"};function r(n,e,d,c,l,p){return s(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="scraping-internal-telemetry" tabindex="-1">Scraping internal telemetry <a class="header-anchor" href="#scraping-internal-telemetry" aria-label="Permalink to &quot;Scraping internal telemetry&quot;">​</a></h1><p>Agent Data Plane exposes internal telemetry as OpenMetrics text on the unprivileged API endpoint. You can scrape this endpoint to collect ADP process, pipeline, and component metrics.</p><h2 id="endpoints" tabindex="-1">Endpoints <a class="header-anchor" href="#endpoints" aria-label="Permalink to &quot;Endpoints&quot;">​</a></h2><p>ADP serves its full internal telemetry at <code>/metrics</code> on <code>data_plane.api_listen_address</code>, also called the &quot;unprivileged API address.&quot; The default address uses port <code>5100</code>, so a default local scrape target is:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:5100/metrics</span></span></code></pre></div><p>This is an ADP-local endpoint. When ADP registers with the Core Agent, the Core Agent also exposes ADP series on its own <code>/telemetry</code> endpoint alongside Core Agent series. Prefer the Core Agent endpoint when you want a combined view; use ADP&#39;s <code>/metrics</code> endpoint when you want ADP telemetry only. ADP series on the Core Agent endpoint carry an <code>emitter</code> label so you can distinguish them from Core Agent series.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>The Core Agent serves <code>/telemetry</code> even when <code>telemetry.enabled</code> is <code>false</code>. Enabling that key adds other Core Agent telemetry; it is not a prerequisite for the combined scrape. ADP ignores the key and registers its local <code>/metrics</code> route independently.</p></div><h2 id="configure-a-scrape" tabindex="-1">Configure a scrape <a class="header-anchor" href="#configure-a-scrape" aria-label="Permalink to &quot;Configure a scrape&quot;">​</a></h2><p>For ADP-only telemetry, target its unprivileged API address. For the combined view, use <code>http://localhost:5000/telemetry</code> when your scraper runs on the Core Agent host. The Core Agent&#39;s expvar server listens on loopback at port <code>5000</code> by default; if you change <code>expvar_port</code>, update the port in your scrape target. These examples assume the scraper can reach that loopback listener.</p><h3 id="datadog-agent-openmetrics-check" tabindex="-1">Datadog Agent OpenMetrics check <a class="header-anchor" href="#datadog-agent-openmetrics-check" aria-label="Permalink to &quot;Datadog Agent OpenMetrics check&quot;">​</a></h3><p>To scrape ADP-only telemetry with the Datadog Agent, configure the <a href="https://docs.datadoghq.com/integrations/openmetrics/" target="_blank" rel="noreferrer">OpenMetrics check</a> with ADP&#39;s telemetry endpoint. To collect both Core Agent and ADP series in one scrape, target the Core Agent&#39;s <code>/telemetry</code> endpoint instead.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">instances</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">openmetrics_endpoint</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">http://127.0.0.1:5100/metrics</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    namespace</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">agent_data_plane</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    metrics</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;.*&quot;</span></span></code></pre></div><p>For a combined Core Agent and ADP scrape, use the Core Agent&#39;s telemetry listener rather than <code>data_plane.api_listen_address</code>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">instances</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">openmetrics_endpoint</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">http://localhost:5000/telemetry</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    namespace</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">datadog_agent</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    metrics</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;dogstatsd__processed&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;transactions__.*&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;aggregator__flush&quot;</span></span></code></pre></div><p>Use narrower metric patterns when you do not need the full Core Agent telemetry surface. The metric names in this guide are exposition names; the OpenMetrics check may prefix submitted Datadog metric names with the configured namespace.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>The OpenMetrics check submits collected series as custom metrics. Use explicit metric names or narrower patterns when you do not need the full ADP telemetry surface.</p></div><h3 id="prometheus" tabindex="-1">Prometheus <a class="header-anchor" href="#prometheus" aria-label="Permalink to &quot;Prometheus&quot;">​</a></h3><p>For Prometheus-style scraping, use ADP&#39;s unprivileged API address for ADP-only telemetry. To collect the combined Core Agent and ADP view, use the Core Agent telemetry listener and set <code>metrics_path</code> to <code>/telemetry</code> instead.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">scrape_configs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">job_name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">agent-data-plane</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    metrics_path</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/metrics</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    static_configs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">targets</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">          - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">127.0.0.1:5100</span></span></code></pre></div><p>To scrape the combined Core Agent and ADP view instead, target the Core Agent telemetry listener:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">scrape_configs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">job_name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">core-agent-telemetry</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    metrics_path</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/telemetry</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    static_configs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">targets</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">          - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">localhost:5000</span></span></code></pre></div><p>If you change <code>data_plane.api_listen_address</code>, update the ADP-local scrape target to match the configured host and port.</p><h2 id="migrate-legacy-expvar-consumers" tabindex="-1">Migrate legacy expvar consumers <a class="header-anchor" href="#migrate-legacy-expvar-consumers" aria-label="Permalink to &quot;Migrate legacy expvar consumers&quot;">​</a></h2><ol><li>Identify the expvar path your dashboard or <code>go_expvar</code> check reads from the Core Agent&#39;s <code>/debug/vars</code> endpoint. Do not substitute an entire metric family for a path that selects labels.</li><li>Use the table below to find the corresponding ADP series on the Core Agent&#39;s <code>/telemetry</code> endpoint. Select the listed labels and keep <code>emitter</code> separate when comparing ADP and local traffic. Use counter rates for dashboards rather than adding raw counter values across restarts.</li><li>If you rely on the existing expvar path, deploy a Core Agent version with the <a href="https://github.com/DataDog/datadog-agent/pull/58438" target="_blank" rel="noreferrer">ADP expvar bridge</a>. The bridge is a separate Core Agent change; Saluki&#39;s RAR remappings alone do not update <code>/debug/vars</code>. Until that change is available, query <code>/telemetry</code> directly for ADP values.</li></ol><p>The Core Agent&#39;s <code>/telemetry</code> endpoint includes ADP series alongside local Agent series. The bridge combines ADP and local values only for its explicit mappings; a metric on <code>/telemetry</code> does not automatically become an expvar. The table shows the legacy paths and RAR metric families used by the proposed bridge, including known gaps. Paths below are relative to <code>/debug/vars</code>. The mappings identify series and selectors, not a guarantee that the two processes count every event at the same stage.</p><table tabindex="0"><thead><tr><th>Legacy expvar paths</th><th>ADP series on <code>/telemetry</code></th><th>Fidelity and bridge status</th></tr></thead><tbody><tr><td><code>dogstatsd-udp/Packets</code>, <code>dogstatsd-udp/PacketReadingErrors</code></td><td><code>dogstatsd__udp_packets</code>; packet-reading errors select <code>state=&quot;error&quot;</code></td><td>The bridge maps both paths; the packet total includes the relevant packet states.</td></tr><tr><td><code>dogstatsd-uds/Packets</code>, <code>dogstatsd-uds/PacketReadingErrors</code></td><td><code>dogstatsd__uds_packets</code>; select <code>transport=&quot;unix&quot;</code> or <code>&quot;unixgram&quot;</code>, and <code>state=&quot;error&quot;</code> for errors</td><td>The bridge maps both paths and combines the two UDS transports.</td></tr><tr><td><code>dogstatsd/MetricPackets</code>, <code>MetricParseErrors</code>, <code>EventPackets</code>, <code>EventParseErrors</code>, <code>ServiceCheckPackets</code>, <code>ServiceCheckParseErrors</code></td><td><code>dogstatsd__processed{message_type=...,state=...}</code></td><td>Select both labels: <code>metrics</code>, <code>events</code>, or <code>service_checks</code>, crossed with <code>ok</code> or <code>error</code>. The bridge maps each path separately.</td></tr><tr><td><code>dogstatsd-uds/OriginDetectionErrors</code></td><td><code>dogstatsd__uds_origin_detection_error</code></td><td>Known gap: the bridge expects <code>dogstatsd__uds_origin_detection_errors</code> (plural), so the current RAR family name does not match. Do not assume this expvar receives the ADP value yet.</td></tr><tr><td><code>forwarder/Transactions/Success</code></td><td><code>transactions__success</code></td><td>The bridge maps the series. ADP doesn&#39;t count API key validation requests as transactions, matching the legacy value.</td></tr><tr><td><code>forwarder/Transactions/Errors</code>, <code>HTTPErrors</code>, and <code>ErrorsByType/*</code></td><td><code>transactions__errors{error_type=...}</code> and <code>transactions__http_errors</code></td><td>The bridge maps <code>Errors</code> and <code>HTTPErrors</code>. <strong>Known gap:</strong> its <code>ErrorsByType/*</code> selectors do not match ADP&#39;s error-type labels, so those paths do not receive the corresponding ADP counts. For ADP queries, select <code>dns_error</code>, <code>tls_error</code>, <code>connection_error</code>, or <code>wrote_request_error</code> on <code>transactions__errors</code>; there is no ADP <code>invalid_request</code> label for <code>SentRequestErrors</code>.</td></tr><tr><td><code>forwarder/Transactions/RetryQueueSize</code></td><td><code>transactions__retry_queue_size{domain=...}</code></td><td>The bridge combines the per-domain queue gauges into the legacy value. Compare queue ownership across processes when interpreting the combined size.</td></tr><tr><td><code>forwarder/Transactions/DroppedOnInput</code></td><td><code>transactions__dropped</code></td><td>Not equivalent and <strong>not bridged</strong>: ADP counts a broader set of failed requests, not only retry-queue drops. Query the ADP series separately.</td></tr><tr><td><code>aggregator/DogstatsdContexts</code>, <code>DogstatsdMetricSample</code>, <code>SeriesFlushed</code></td><td><code>aggregator__dogstatsd_contexts</code>, <code>aggregator__processed{data_type=&quot;dogstatsd_metrics&quot;}</code>, <code>aggregator__flush{data_type=&quot;series&quot;}</code></td><td>Mapped by the bridge. The contexts value is an INFO-level context-resolver gauge, not the aggregate-transform gauge; the two can have different lifetimes. The sample and flushed-series values are counters.</td></tr><tr><td><code>aggregator/Event</code>, <code>ServiceCheck</code>, <code>EventsFlushed</code>, <code>ServiceCheckFlushed</code></td><td><code>aggregator__processed</code> and <code>aggregator__flush</code>, selecting <code>data_type=&quot;events&quot;</code> or <code>&quot;service_checks&quot;</code></td><td>Mapped by the bridge with a distinct <code>data_type</code> selector for each path. These include encoder-proxy telemetry; compare semantics before replacing existing dashboards.</td></tr><tr><td><code>aggregator/FlushCount/*/LastFlush</code>, <code>Flush/*FlushTime/LastFlush</code></td><td><code>aggregator__flush_count{flush_type=...}</code>, <code>aggregator__flush_time{flush_type=...}</code></td><td>Available counts and timings are mapped by the bridge. These are per-process snapshots, not meaningful combined totals in an OpenMetrics query; keep them separate by <code>emitter</code>. Not every legacy timing has an ADP equivalent.</td></tr><tr><td><code>aggregator/NumberOfFlush</code></td><td><code>aggregator__number_of_flush</code></td><td>Mapped. The ADP counter is INFO-level and counts attempts when the aggregation state is nonempty, including failed flushes or attempts that produce no points. It is not an exact substitute.</td></tr><tr><td>Splitter and serializer</td><td>V3 metrics such as <code>serializer__v3_payload_split_reason{reason=&quot;item_too_big&quot;}</code></td><td>Not bridged. The Core Agent no longer has the legacy splitter expvar subtree. ADP splits proactively rather than using a split-and-retry loop; the V3 payload-split give-up counter is not emitted.</td></tr><tr><td>Scheduler and Logs Agent</td><td>No ADP series</td><td>These paths are unaffected and remain local to the Agent.</td></tr></tbody></table><p>The bridge does not cover every aggregator field (for example, Core Agent-owned check telemetry or flush timings with no ADP analogue). Query <code>/telemetry</code> for ADP-specific metrics that have no legacy expvar equivalent.</p><h3 id="contexts-grouped-by-origin" tabindex="-1">Contexts grouped by origin <a class="header-anchor" href="#contexts-grouped-by-origin" aria-label="Permalink to &quot;Contexts grouped by origin&quot;">​</a></h3><p>Set <code>telemetry.dogstatsd_origin: true</code> to emit <code>aggregator__dogstatsd_contexts_by_origin</code> on <code>/telemetry</code>. The default is <code>false</code>. This gauge groups active DogStatsD contexts by their complete resolved origin-tag set. Contexts without resolved origin tags are omitted, so the gauge stays empty unless <code>dogstatsd_origin_detection</code> is also enabled. It is not a legacy expvar and does not replace <code>aggregator/DogstatsdContexts</code>.</p><p>The gauge exports up to 199 distinct origin groups and one <code>origin_overflow=&quot;true&quot;</code> group for additional sets or sets exceeding 32 tags or 4096 bytes of encoded labels. Groups keep their assignment until their contexts expire, so an origin&#39;s own series is too low while the overflow group holds some of its contexts. Check the overflow group when comparing per-origin counts against the total. An emptied group reports 0 briefly before its series is removed.</p><p>Each tag key becomes one label. Keys that aren&#39;t valid Prometheus label names, or that clash with labels ADP adds, use the reversible Prometheus <code>U__</code> escaping: for example, <code>git.commit.sha</code> becomes <code>U__git_2e_commit_2e_sha</code>. A key with several values gets one label that lists them sorted and comma-separated, such as <code>kube_service=&quot;api,worker&quot;</code>, with commas and backslashes inside a value escaped by a backslash. Bare tags and tags with empty values are listed in the <code>origin_bare_tags</code> label. ADP escapes special characters in label values according to Prometheus text exposition rules.</p><p>The six processed-message expvar metrics share <code>dogstatsd__processed</code>, so select both labels when querying <code>/telemetry</code>. For example, metric packets use <code>message_type=&quot;metrics&quot;</code> and <code>state=&quot;ok&quot;</code>:</p><div class="language-promql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">promql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sum(</span></span>
<span class="line"><span>  rate(dogstatsd__processed{emitter=&quot;Agent Data Plane&quot;,message_type=&quot;metrics&quot;,state=&quot;ok&quot;}[5m])</span></span>
<span class="line"><span>)</span></span></code></pre></div><p>Change <code>state</code> to <code>error</code> to query metric parse errors. The emitter value is the registered display name; replace <code>Agent Data Plane</code> if your deployment uses another name.</p><p>To combine the compatible series-flush counters, calculate the rate for each emitter before aggregating so counter resets remain visible:</p><div class="language-promql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">promql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sum without (emitter) (rate(aggregator__flush{data_type=&quot;series&quot;}[5m]))</span></span></code></pre></div><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p>If scraping fails, verify that ADP is listening on the unprivileged API address:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:5100/metrics</span></span></code></pre></div><p>If you configured a non-default <code>data_plane.api_listen_address</code>, use that address instead of <code>127.0.0.1:5100</code>.</p><p>If the endpoint returns data but dashboards do not populate, check whether the dashboard expects ADP-native names from <code>/metrics</code> or RAR names from the Core Agent&#39;s <code>/telemetry</code> endpoint.</p><p>If you are investigating DogStatsD-specific counters, the internal telemetry endpoint includes aggregate DogStatsD counters such as processed message counts, packet and byte counts, packet pool usage, and channel latency. This is separate from the on-demand DogStatsD statistics API documented in <a href="./configuration/configuration">Agent Data Plane configuration</a>.</p>`,42)])])}const u=t(i,[["render",r]]);export{g as __pageData,u as default};
